import {angleMark} from './angle-renderer.js?v=11';
import {localToWorld,worldToLocal,distance,segmentDistance,eraseInk} from './geometry.js?v=3.1';
import {createObject} from './core.js?v=3.1';
export const CM=40;
export const closedShape=o=>o.type==='ShapeObject'&&o.points?.length>=3&&!['line','arrow'].includes(o.kind);
export function vertices(o){return o.points?.map(p=>localToWorld(p,o))??[]}
export function edges(o){const ps=vertices(o);return ps.slice(0,closedShape(o)?ps.length:Math.max(0,ps.length-1)).map((a,i)=>({a,b:ps[(i+1)%ps.length],index:i}))}
function area(ps){return ps.reduce((sum,p,i)=>{const q=ps[(i+1)%ps.length];return sum+p.x*q.y-q.x*p.y},0)/2}
export function angleAt(o,i){if(o.curved||o.points?.some(p=>['smooth','symmetric'].includes(p.nodeType)))return null;const ps=vertices(o),n=ps.length;if(n<3||(!closedShape(o)&&(i===0||i===n-1)))return null;const p=ps[i],a=ps[(i+n-1)%n],b=ps[(i+1)%n];if(distance(p,a)<1e-6||distance(p,b)<1e-6)return null;const start=Math.atan2(a.y-p.y,a.x-p.x),end=Math.atan2(b.y-p.y,b.x-p.x);let sweep=(end-start+Math.PI*2)%(Math.PI*2);if(closedShape(o)){if(area(ps)>=0)sweep-=Math.PI*2}else if(sweep>Math.PI)sweep-=Math.PI*2;return {p,start,sweep,degrees:Math.abs(sweep)*180/Math.PI,radius:Math.min(28,distance(p,a)*.25,distance(p,b)*.25)}}
export function suggestNames(o,index,name){if(!/^[A-Za-z]$/.test(name))return [];const ps=vertices(o),direction=closedShape(o)&&area(ps)<0?-1:1,used=new Set(o.points.map(p=>p.label).filter(Boolean));let letter=name.toUpperCase().charCodeAt(0),result=[];for(let step=1;step<ps.length;step++){const i=(index+direction*step+ps.length)%ps.length;if(o.points[i].label)continue;let candidate,attempts=0;do{letter=letter===90?65:letter+1;candidate=String.fromCharCode(letter);attempts++}while((used.has(candidate)||candidate===name.toUpperCase())&&attempts<26);if(attempts>=26)break;used.add(candidate);result.push({index:i,label:candidate})}return result}
export function triangleSAS(a,b,degrees,position={x:0,y:0},style={}){if(![a,b,degrees].every(Number.isFinite)||a<=0||b<=0||a>1000||b>1000||degrees<=0||degrees>=180)throw Error('Invalid triangle');const rad=degrees*Math.PI/180,c=Math.hypot(a-b*Math.cos(rad),b*Math.sin(rad));if(c<1e-6)throw Error('Degenerate triangle');const o=createObject('ShapeObject',{...style,kind:'triangle',position,points:[{x:0,y:0,label:'A',angle:{visible:true,mode:'value'}},{x:a*CM,y:0,label:'B'},{x:b*CM*Math.cos(rad),y:-b*CM*Math.sin(rad),label:'C'}],unitsPerCm:CM});o.points.forEach(p=>p.edgeLabel={mode:'measured',unit:'cm'});return {object:o,opposite:c}}
export function setEdgeLength(o,index,cm){if(!Number.isFinite(cm)||cm<=0||cm>1000)throw Error('Invalid length');const es=edges(o),edge=es[index];if(!edge||distance(edge.a,edge.b)<1e-6)throw Error('Invalid edge');const ratio=cm*(o.unitsPerCm??CM)/distance(edge.a,edge.b),target={x:edge.a.x+(edge.b.x-edge.a.x)*ratio,y:edge.a.y+(edge.b.y-edge.a.y)*ratio};const next=(index+1)%o.points.length;Object.assign(o.points[next],worldToLocal(target,o));o.points[index].edgeLabel={mode:'measured',unit:'cm'};o.unitsPerCm??=CM;o.irregular=true;if(!['line','arrow','polyline','curve','triangle'].includes(o.kind))o.kind='polygon';}
export function partAt(o,p,tolerance){const ps=vertices(o);let nearest=null,best=tolerance;ps.forEach((q,i)=>{const d=distance(q,p);if(d<best){best=d;nearest={kind:'point',index:i,point:q}}});if(nearest)return nearest;for(const edge of edges(o)){const d=segmentDistance(p,edge.a,edge.b);if(d<best){best=d;nearest={kind:'edge',index:edge.index,point:{x:(edge.a.x+edge.b.x)/2,y:(edge.a.y+edge.b.y)/2}}}}return nearest}
export function outline(o){if(o.points?.length){let ps=vertices(o);if(o.curved||o.points.some(p=>p.nodeType==='smooth'||p.nodeType==='symmetric')){ps=[];for(let i=1;i<o.points.length;i++){const a=o.points[i-1],b=o.points[i],before=o.points[i-2]??a,next=o.points[i+1]??b;const curved=o.curved||['smooth','symmetric'].includes(a.nodeType)||['smooth','symmetric'].includes(b.nodeType);for(let j=0;j<=20;j++){const t=j/20,u=1-t;ps.push(localToWorld(curved?{x:u*u*u*a.x+3*u*u*t*(a.x+(b.x-before.x)/6)+3*u*t*t*(b.x-(next.x-a.x)/6)+t*t*t*b.x,y:u*u*u*a.y+3*u*u*t*(a.y+(b.y-before.y)/6)+3*u*t*t*(b.y-(next.y-a.y)/6)+t*t*t*b.y}:{x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t},o))}}}if(closedShape(o))ps.push(ps[0]);return ps}const w=o.width??0,h=o.height??0;if(['circle','ellipse','arc','semicircle'].includes(o.kind)){const half=['arc','semicircle'].includes(o.kind),ps=Array.from({length:129},(_,i)=>{const a=(half?Math.PI:0)+i/128*Math.PI*(half?1:2);return localToWorld({x:w/2+Math.cos(a)*w/2,y:(half?h:h/2)+Math.sin(a)*(half?h:h/2)},o)});if(o.kind==='semicircle')ps.push(ps[0]);return ps}if(o.kind==='rounded'){const r=Math.min(16,w/4,h/4),ps=[];for(const [cx,cy,start]of [[w-r,r,-Math.PI/2],[w-r,h-r,0],[r,h-r,Math.PI/2],[r,r,Math.PI]])for(let j=0;j<=16;j++){const a=start+j/16*Math.PI/2;ps.push(localToWorld({x:cx+Math.cos(a)*r,y:cy+Math.sin(a)*r},o))}ps.push(ps[0]);return ps}return [{x:0,y:0},{x:w,y:0},{x:w,y:h},{x:0,y:h},{x:0,y:0}].map(p=>localToWorld(p,o))}
function intersects(a,b,c,d){const cross=(p,q,r)=>(q.x-p.x)*(r.y-p.y)-(q.y-p.y)*(r.x-p.x),x=cross(a,b,c),y=cross(a,b,d),z=cross(c,d,a),w=cross(c,d,b);return x*y<0&&z*w<0}
export function eraseObjects(objects,a,b,r,mode){const kept=objects.filter(o=>{if(o.locked||!['ShapeObject','VectorPath'].includes(o.type))return true;const ps=outline(o),radius=r+o.strokeWidth*Math.max(Math.abs(o.scale.x),Math.abs(o.scale.y))/2;return !ps.some((p,i)=>{if(!i)return false;const q=ps[i-1];return intersects(a,b,p,q)||Math.min(segmentDistance(p,a,b),segmentDistance(q,a,b),segmentDistance(a,p,q),segmentDistance(b,p,q))<=radius})});return eraseInk(kept,a,b,r,mode)}
export function renderAnnotations(ctx,o,dark){if(!o.points||o.type==='InkStroke')return;ctx.save();ctx.globalAlpha=o.opacity??1;ctx.fillStyle=dark?'#eeeeef':'#25262a';ctx.strokeStyle=dark?'#b4bce0':'#627398';ctx.lineWidth=1.2;ctx.setLineDash([]);ctx.font='15px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';const ps=vertices(o),centre={x:ps.reduce((s,p)=>s+p.x,0)/ps.length,y:ps.reduce((s,p)=>s+p.y,0)/ps.length};o.points.forEach((node,i)=>{const p=ps[i];if(node.label){let dx=p.x-centre.x,dy=p.y-centre.y,d=Math.hypot(dx,dy)||1;ctx.fillText(node.label,p.x+dx/d*20,p.y+dy/d*20)}const angle=angleAt(o,i);if(node.angle?.visible&&angle){const {start,sweep,radius}=angle;const showValue=angleMark(ctx,{p,start,sweep,radius,rightAngleDisplay:node.angle.rightAngleDisplay??'marker-only'});const text=node.angle.mode==='value'?`${Number(angle.degrees.toFixed(1))}°`:node.angle.mode==='x'?'x':node.angle.mode==='theta'?'θ':node.angle.mode==='custom'?(node.angle.text??''):'';if(text&&(node.angle.mode!=='value'||showValue)){const a=start+sweep/2;ctx.fillText(text,p.x+Math.cos(a)*(radius+17),p.y+Math.sin(a)*(radius+17))}}});for(const edge of edges(o)){const data=o.points[edge.index].edgeLabel;if(!data||data.mode==='none')continue;const value=data.mode==='measured'?Number((distance(edge.a,edge.b)/(o.unitsPerCm??CM)).toFixed(2)):data.value;if(value===undefined||value==='')continue;const dx=edge.b.x-edge.a.x,dy=edge.b.y-edge.a.y,d=Math.hypot(dx,dy)||1,sign=closedShape(o)&&area(ps)<0?-1:1;ctx.fillText(`${value}${data.unit?' '+data.unit:''}`,(edge.a.x+edge.b.x)/2+dy/d*19*sign,(edge.a.y+edge.b.y)/2-dx/d*19*sign)}ctx.restore()}
